import { z } from 'zod';

export const AddAllowanceSchema = z.object({
    employee_id: z.string().min(1, 'Employee name field is required.'),
    date: z.date({
        required_error: 'Date is required',
    }),
    allowance_type: z.string().min(1, 'Allowance type is required'),
    name: z.string().min(1, 'Name is required'),
    status: z.string().min(1, 'Status is required'),
    amount: z.string().min(1, 'Amount is required'),
    currency: z.string().min(1, 'Currency is required'),
    description: z.string().min(1, 'Description is required'),
});

export type AddAllowanceFormValues = z.infer<typeof AddAllowanceSchema>;
