import { Form } from '@/components/ui/form';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { apiGet, apiPost } from '@/lib/axios/axios-utils';
import { endpoints } from '@/lib/axios/axios-global';
import { useEffect, useMemo, useState } from 'react';
import { Employee } from '@/types/employee.types';
import { format } from 'date-fns';
import DayPickerInputForm from '@/components/forms/DayPickerInputForm';
import SelectInputForm from '@/components/forms/SelectInputForm';
import { toast } from 'sonner';
import TextInputForm from '@/components/forms/TextInputForm';
import { AddAllowanceFormValues, AddAllowanceSchema } from '../../schemas/addAllowance/add-allowance-schema';
import TextAreaInputForm from '@/components/forms/TextAreaInputForm';
import Submission from './Submission';

interface Props {
    employee?: Employee | null;
    setAddAllowance: (value: boolean) => void;
}

export default function AddAllowanceForm({ employee, setAddAllowance }: Props) {
    const [error, setError] = useState<string | null>(null);
    const [loading, setLoading] = useState(false);
    const [employees, setEmployees] = useState<{ name: string; value: string }[]>([]);
    const [employeesError, setEmployeesError] = useState<string | null>(null);
    const [showSuccessPopup, setShowSuccessPopup] = useState(false);
    const [showCancelPopup, setShowCancelPopup] = useState(false);

    const defaultValues = useMemo(
        () => ({
            employee_id: '',
        }),
        [employee],
    );

    const form = useForm<AddAllowanceFormValues>({
        resolver: zodResolver(AddAllowanceSchema),
        defaultValues,
    });

    const onSubmit = async (data: AddAllowanceFormValues) => {
        setLoading(true);
        setError(null); // Clear previous errors
        const formatedData = {
            ...data,
            date: format(data.date, 'yyyy-MM-dd'),
        };
        try {
            await apiPost({
                endpoint: employee ? endpoints.allowance.update + employee.id : endpoints.allowance.create,
                body: formatedData,
                config: { headers: { 'Content-Type': 'multipart/form-data' } },
            });

            toast('تم اضافة البدل بنجاح');
            setAddAllowance(false);
        } catch (error: any) {
            if (error.response?.data?.errors) {
                // Handle field-specific errors
                Object.entries(error.response.data.errors).forEach(([field, messages]) => {
                    form.setError(field as any, {
                        type: 'manual',
                        message: (messages as string[]).join(', '),
                    });
                });
            } else {
                // Handle generic error
                let errorMessage = 'حدث خطأ أثناء إرسال البيانات. يرجى المحاولة مرة أخرى.';
                if (error.response) {
                    errorMessage = error.response.data.msg || errorMessage;
                } else if (error.request) {
                    errorMessage = 'تعذر الاتصال بالخادم. يرجى التحقق من اتصالك بالإنترنت.';
                }
                setError(errorMessage);
            }
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        const fetchEmployees = async () => {
            try {
                const response = await apiGet({ endpoint: endpoints.employee.list });

                const options = response.data.data.data.map((employee: Employee) => {
                    return { name: employee.name, value: String(employee.id) };
                });
                setEmployees(options);
                setEmployeesError(null);
            } catch (error) {
                setEmployeesError('Error fetching employees. Please try again later.');
            }
        };

        fetchEmployees();
    }, []);

    return (
        <>
            <Form {...form}>
                <form onSubmit={form.handleSubmit(onSubmit)} className="mt-6">
                    {error && (
                        <div className="mb-4 p-4 bg-red-100 border border-red-400 text-red-700 rounded-lg">
                            <div className="flex justify-between items-center">
                                <span className="">{error}</span>
                                <button onClick={() => setError(null)} className="text-red-700 hover:text-red-900">
                                    ×
                                </button>
                            </div>
                        </div>
                    )}
                    <div className="grid grid-cols-2 gap-x-6 gap-y-3">
                        <TextInputForm name="name" label="اسم البدل" placeholder="نوع البدل - تامينات - ساعات اضافية" />
                        <TextInputForm name="amount" type="number" label="المبلغ" placeholder="300" />
                        <DayPickerInputForm name="date" label="التاريخ" placeholder="2025/04/30" />
                        <SelectInputForm
                            name="currency"
                            label="العملة"
                            options={[
                                { name: 'ريال سعودي', value: 'sar' },
                                { name: 'دولار أمريكي', value: 'usd' },
                            ]}
                            placeholder="العملة"
                        />

                        <TextAreaInputForm
                            className="flex flex-col min-h-[157px]"
                            name="description"
                            label="وصف البدل"
                            placeholder="وصف البدل"
                        />
                        {/* <SelectInputForm
                            name="allowance_type"
                            options={[
                                { name: 'بدل', value: 'allowances' },
                                { name: 'خصومات', value: 'deductions' },
                            ]}
                            label="نوع البدل"
                            placeholder="ادخل نوع البدل"
                        /> */}
                    </div>
                    <div className="flex flex-row gap-4 mt-12">
                 
                        <Submission
                            loading={loading}
                            showSuccessPopup={showSuccessPopup}
                            setShowSuccessPopup={setShowSuccessPopup}
                            showCancelPopup={showCancelPopup}
                            setShowCancelPopup={setShowCancelPopup}
                        />
                    </div>
                </form>
            </Form>
        </>
    );
}
