import SuccessPopup from '@/components/Popups/SuccessPopup';
import { SecondaryButton } from '@/components/buttons/SecondaryButton';
import { PrimaryButton } from '@/components/buttons/PrimaryButton';
import CancelPopup from '@/components/Popups/CancelPopup';
import { MaintenanceOrder } from '@/types/maintenance';
import { useNavigate } from 'react-router-dom';

interface Props {
    maintenanceOrder?: MaintenanceOrder | null;
    showSuccessPopup: boolean;
    setShowSuccessPopup: (value: boolean) => void;
    showCancelPopup: boolean;
    setShowCancelPopup: (value: boolean) => void;
    loading: boolean;
}
export default function Submission({
    maintenanceOrder,
    setShowCancelPopup,
    setShowSuccessPopup,
    showCancelPopup,
    showSuccessPopup,
    loading,
}: Props) {
    const navigate = useNavigate();

    const handleAddAnother = () => {
        setShowSuccessPopup(false);
    };
    return (
        <>
            <div className="flex flex-row justify-end w-full items-center mt-8">
                {maintenanceOrder ? (
                    <SecondaryButton
                        type="button"
                        className="xl:px-[87px] xl:py-3 text-[#A21515] border border-red-error-50 xl:font-semibold bg-red-error-50"
                        onClick={() => setShowCancelPopup(true)}
                    >
                        إلغاء البدل
                    </SecondaryButton>
                ) : (
                    <SecondaryButton
                        type="button"
                        className="xl:px-[87px] xl:py-3 border bg-[#FFE9E9] border-[#E8EFF6] text-[#A21515] xl:font-semibold hover:bg-[#d8bebe] hover:border-[#a13861] hover:text-[#A21515]"
                        onClick={() => setShowCancelPopup(true)}
                    >
                        الغاء
                    </SecondaryButton>
                )}
                <div>
                    {maintenanceOrder ? (
                        <PrimaryButton className="xl:px-[91px] xl:py-3 xl:font-semibold ms-6" disabled={loading}>
                            {loading ? 'جاري التحميل...' : 'حفظ التغييرات'}
                        </PrimaryButton>
                    ) : (
                        <PrimaryButton className="xl:px-[125px] xl:py-3 xl:font-semibold ms-6" disabled={loading}>
                            {loading ? 'جاري التحميل...' : 'اضافة'}
                        </PrimaryButton>
                    )}
                </div>
            </div>
            <CancelPopup
                open={showCancelPopup}
                onClickButton1={() => {
                    setShowCancelPopup(false);
                }}
                onClickButton2={() => {
                    navigate('/payroll');
                    setShowCancelPopup(false);
                }}
                text1={maintenanceOrder ? 'تم الغاء تعديل البدل' : 'تم الغاء البدل'}
                text2={
                    maintenanceOrder
                        ? 'أنت على وشك إلغاء عملية تعديل البدل دون إكمال البيانات المطلوبة. سيتم تجاهل جميع البيانات المدخلة، هل أنت متأكد؟'
                        : 'أنت على وشك إلغاء عملية إضافة البدل دون إكمال البيانات المطلوبة. سيتم تجاهل جميع البيانات المدخلة، هل أنت متأكد؟'
                }
                textButton1="إكمال البدل"
                textButton2="إلغاء البدل"
            />
            <SuccessPopup
                text1={maintenanceOrder ? 'تم تعديل  بنحاح' : 'تم إضافة البدل  بنحاح'}
                text2={maintenanceOrder ? 'تم تعديل البدل بنجاح.' : 'تم إضافة البدل  بنجاح.'}
                textButton1="العودة لقائمة البدلات"
                textButton2={maintenanceOrder ? 'العودة لقائمة البدلات' : 'إضافة بدل جديد'}
                open={showSuccessPopup}
                onAddAnother={handleAddAnother}
                onReturnToList={() => {
                    navigate('/payroll');
                    setShowSuccessPopup(false);
                }}
            />
        </>
    );
}
